function xsPromiseWrapper(func, ...args){
	
	var rv, out;
	return myPromise = new Promise(function(resolve, reject){
		/**
		* Loading the WASM might take time within which
		* we may get a request to use any of the compiled functions.
		* This leads to errors which at times is not noticable and requires
		* the user to retry the action.
		* To avoid this all the WASM calls are wrapped as a Promise
		* where we wait and invoke the corresponding function only
		* after the WASM is completely loaded.
		* 'setInterval' is used for the wait and watch functionality.
		* 'onRuntimeInitialized' callback is used to conclude whether WASM is loaded.
		**/
		var intervalCtx = setInterval(function(){
			if(WASMLOADED == true) 
			{
				clearInterval(intervalCtx);
				[rv, out] = func(...args);
				if(rv == 0) resolve(out);
				else reject(out, rv);
			}
			else console.log("Waiting to load WASM ...");
		}, 100);
	});
}
