const XS_DIGEST_BLOCK_FIRST = 1;
const XS_DIGEST_BLOCK_FINAL = 2;
const XS_DIGEST_BLOCK_INTER = 4;


/**
type
	0 -> encryption, else -> decryption
infoAB
	fetched from xorkeesign
dataAB
	trapped/framed by extension

Returns the result (number) and the encrypted/decrypted payload as multiple values
Result Codes:
	0 -> success (payload is arraybuffer)
	-100 -> Not registered in xorkee (payload is a string)
	others -> error (payload is a string)
**/
function xsGetPayload(type, infoAB, dataAB)
{
	var infobuf = new Uint8Array(infoAB, 0, infoAB.byteLength);
	var info = XORKEESIGN._malloc(infoAB.byteLength);
	XORKEESIGN.HEAPU8.set(infobuf, info);
	
	var databuf = new Uint8Array(dataAB, 0, dataAB.byteLength);
	var data = XORKEESIGN._malloc(dataAB.byteLength);
	XORKEESIGN.HEAPU8.set(databuf, data);
	
	var datalenbuf = new Uint32Array(1);
	var datalen = XORKEESIGN._malloc(datalenbuf.length * datalenbuf.BYTES_PER_ELEMENT);
	XORKEESIGN.setValue(datalen, dataAB.byteLength, "i32");	//set the length of the input data buffer
	
	var outbuf = new Uint32Array(1);
	var out = XORKEESIGN._malloc(outbuf.length * outbuf.BYTES_PER_ELEMENT);
	XORKEESIGN.setValue(out, 0, "i32");	//NULL set
	
	var outlenbuf = new Uint32Array(1);
	var outlen = XORKEESIGN._malloc(outlenbuf.length * outlenbuf.BYTES_PER_ELEMENT);
	XORKEESIGN.setValue(outlen, 0, "i32");	//NULL set
	
	var i, rv, len, ptr, errstr, payload;
	
	rv = xorkeesignGetPayload(type, info, data, dataAB.byteLength, out, outlen);
	if(rv == 0)
	{
		len = XORKEESIGN.getValue(outlen, "i32");
		if(len > 0)
		{
			ptr = XORKEESIGN.getValue(out, "i32");
			if(ptr > 0)
			{
				payload = new Uint8Array(len);
				for(i=0; i<len; i++) payload[i] = XORKEESIGN.getValue(ptr+i, "i8");
				XORKEESIGN._free(ptr);
			}
			else
			{
				errstr = "ERROR: XS | Failed to extract the Encrypt/Decrypt payload";
			}
		}
		else
		{
			errstr = "ERROR: XS | Failed to Encrypt/Decrypt";
		}
	}
	else if(rv == -100)
	{
		errstr = "INFO: XS | Not registered in xorkee";
	}
	else
	{
		errstr = "ERROR: XS | Encrypt/Decrypt Failed";
	}
	
	XORKEESIGN._free(info);
	XORKEESIGN._free(data);
	XORKEESIGN._free(datalen);
	XORKEESIGN._free(out);
	XORKEESIGN._free(outlen);
	return [rv, (rv==0)?payload:errstr];
}

