function xsGetNotificationId(dataAB)
{
	var databuf = new Uint8Array(dataAB, 0, dataAB.byteLength);
	var data = XORKEESIGN._malloc(dataAB.byteLength);
	XORKEESIGN.HEAPU8.set(databuf, data);
	
	const len = 16;
	var valbuf = new Uint8Array(len);
	var val = XORKEESIGN._malloc(valbuf.length * valbuf.BYTES_PER_ELEMENT);
	//XORKEESIGN.setValue(val, 0, "i8");	//NULL set
	
	var i, str, code;
	
	_getNotificationId(data, dataAB.byteLength, val);
	str = "";
	for(i=0; i<len; i++)
	{
		if((code = XORKEESIGN.getValue(val+i, "i8")) == 0) break;
		str += String.fromCharCode(code);
	}
	
	XORKEESIGN._free(val);
	XORKEESIGN._free(data);
	if(str.length==0) return [-1, "ERROR: XS | Unable to get notification Id"];
	else return [0, str.toUpperCase()];
}

/*
* The following are the supported 'paramtype':

"subjectCN", "issuerCN", "serialNo", "publicKey", "class", "subjectDN", "issuerDN", "validFrom", "validTill", "authorityKeyId", "subjectKeyId", "igSubjectDN", "igIssuerDN", "keyUsage"
*/
function xsGetCertParam(certAB, paramtype)
{
	var certbuf = new Uint8Array(certAB, 0, certAB.byteLength);
	var cert = XORKEESIGN._malloc(certAB.byteLength);
	XORKEESIGN.HEAPU8.set(certbuf, cert);
	
	var parambuf = new Uint32Array(1);
	var param = XORKEESIGN._malloc(parambuf.length * parambuf.BYTES_PER_ELEMENT);
	XORKEESIGN.setValue(param, 0, "i32");	//NULL set

	var i, rv, ptr, result;
	
	result = null;
	rv = _xorkeesignGetCertParam(cert, certAB.byteLength, paramtype, param);
	//console.log(paramtype, rv);
	if(rv > 0)
	{
		if(paramtype == "class" || paramtype == "validFrom" || paramtype == "validTill" || paramtype == "keyUsage")	//number data types
		{
			result = rv;
		}
		else
		{
			ptr = XORKEESIGN.getValue(param, "i32");
			if(ptr > 0)
			{
				if(paramtype == "subjectCN" || paramtype == "subjectDN" || paramtype == "issuerDN" || paramtype == "subjectAlternativeName" || paramtype == "igSubjectDN" || paramtype == "igIssuerDN" || paramtype == "issuerCN")	//string data types
				{
					result = "";
					for(i=0; i<rv; i++) result += String.fromCharCode(XORKEESIGN.getValue(ptr+i, "i8"));
				}
				else if(paramtype == "publicKey" || paramtype == "serialNo" || paramtype == "thumbPrint" || paramtype == "authorityKeyId" || paramtype == "subjectKeyId")	//binary data types
				{
					result = new Uint8Array(rv);
					for(i=0; i<rv; i++) result[i] = XORKEESIGN.getValue(ptr+i, "i8");
				}
				
				XORKEESIGN._free(ptr);
			}
		}
	}
	
	XORKEESIGN._free(param);
	XORKEESIGN._free(cert);
	
	if(result == null) return [-1, "ERROR: XS | Unable to get xsGetCertParam"];
	else return [0, result];
}
